  Lemma ak_noacc_cases : forall x, in_rangesb x (vm_noaccess VMM) = true ->
       (pm_meta_map brk0z X <= bv_unsigned x < pm_meta_map brk0z X + 4096)                        (* [comment removed for export] *)
