    \/ (ps_b06 X <= bv_unsigned x < pm_region_info X)                                           (* [comment removed for export] *)
    \/ (pm_region_info X + 4096 <= bv_unsigned x < ps_b06 X + 0x2000011000)                     (* [comment removed for export] *)
